package com.sami.app.sales.receipt;
import com.sami.app.accounting.publicapi.ReceivableSettlementPort; import com.sami.app.common.tenancy.TenantContext; import com.sami.app.common.exception.*; import com.sami.app.treasury.service.TreasuryService; import lombok.RequiredArgsConstructor; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Service @RequiredArgsConstructor public class ReceiptConfirmationOrchestrator { private final JdbcTemplate jdbc; private final TenantContext tenants; private final TreasuryService treasury; private final Optional<ReceivableSettlementPort> settlement;
 @Transactional public Map<String,Object> confirm(Long id){Long t=tenants.requireTenantId(); Map<String,Object> r=jdbc.queryForMap("select * from sales_receipts where tenant_id=? and id=? for update",t,id); if("CONFIRMED".equals(r.get("status")))return r; Long account=(Long)r.get("treasury_account_id"); if(account==null)throw new ApiException(ErrorCode.VALIDATION_FAILED,"Treasury account is required"); if(settlement.isEmpty())throw new ApiException(ErrorCode.OPERATION_NOT_ALLOWED,"Accounting settlement provider is unavailable"); BigDecimal allocated=jdbc.queryForObject("select coalesce(sum(amount),0) from sales_receipt_allocations where tenant_id=? and receipt_id=?",BigDecimal.class,t,id); if(allocated==null||allocated.signum()<=0||allocated.compareTo((BigDecimal)r.get("amount"))>0)throw new ApiException(ErrorCode.VALIDATION_FAILED,"Receipt allocations are invalid"); Long tx=treasury.recordInflow(account,(BigDecimal)r.get("amount"),Instant.now(),"sales-receipt",String.valueOf(r.get("receipt_number")),"Customer receipt"); settlement.get().settle(new ReceivableSettlementPort.ReceiptSettlementCommand(t,(Long)r.get("company_id"),(Long)r.get("branch_id"),(Long)r.get("customer_id"),null,(BigDecimal)r.get("amount"),"IRR",Instant.now(),"SALES-RECEIPT-"+t+"-"+id)); jdbc.update("update sales_receipts set treasury_transaction_id=?,status='CONFIRMED',confirmed_at=now(),version=version+1 where tenant_id=? and id=?",tx,t,id); return jdbc.queryForMap("select * from sales_receipts where tenant_id=? and id=?",t,id); }
}
